def refs():
    return [{"url": u, "title": f"{t}；只取{loc}的能力方向，未複製原題、選項、圖表或答案。", "year": "113-114", "subject": "english", "locator": loc, "observedPattern": "公開英文評量常把主題句、支持細節、句子順序、連接詞、完整句與讀者目的放進生活情境；本課將能力重新改寫。", "reuseDecision": "pattern-only", "status": "recorded", "locatorLevel": "paper"} for u, t, loc in URLS]

